using UnityEngine;
namespace Pigment.Editor {
public static class PigmentTextures {
    public static Texture2D Wood(){int w=1024,h=512;var t=new Texture2D(w,h,TextureFormat.RGBA32,false);var c=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int plank=y/85;float grain=Mathf.Sin(y*.85f+Mathf.Sin(x*.017f+plank)*2.8f)*.026f+Mathf.Sin(y*2.6f+x*.004f)*.017f;float noise=Mathf.PerlinNoise(x*.013f,y*.8f)*.1f;float tone=.37f+Mathf.Sin(plank*13.7f)*.04f+grain+noise;Color col=new Color(tone+.14f,tone+.015f,tone-.15f);if(y%85<2)col*=.38f;c[y*w+x]=col;}t.SetPixels(c);t.Apply();t.wrapMode=TextureWrapMode.Repeat;return t;}
    public static Texture2D Stone(){int w=1024,h=512;var t=new Texture2D(w,h,TextureFormat.RGBA32,false);var c=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int row=y/64;float xx=(x+(row%2)*64)%128;float yy=y%64;int col=(x+(row%2)*64)/128;float tone=.24f+Mathf.Sin(row*37+col*17)*.06f+Mathf.PerlinNoise(x*.12f,y*.12f)*.025f;float bevel=Mathf.Clamp01(Mathf.Min(xx,128-xx,yy,64-yy)/5f);float round=Mathf.Pow(Mathf.Abs((xx-64)/64),8)+Mathf.Pow(Mathf.Abs((yy-32)/32),8);if(round>1.25f)bevel=0;Color stone=new Color(tone+.05f,tone+.025f,tone);c[y*w+x]=Color.Lerp(new Color(.085f,.072f,.055f),stone,bevel);}t.SetPixels(c);t.Apply();t.wrapMode=TextureWrapMode.Repeat;return t;}
    public static Texture2D Parchment(){int w=384,h=512;var t=new Texture2D(w,h,TextureFormat.RGBA32,false);var c=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){float nx=(x-w*.5f)/(w*.5f),ny=(y-h*.5f)/(h*.5f);float edge=Mathf.Clamp01((nx*nx+ny*ny)*.5f);Color p=Color.Lerp(new Color(.91f,.83f,.64f),new Color(.66f,.5f,.29f),edge);float r=Mathf.Sqrt((x-192)*(x-192)+(y-285)*(y-285));bool ink=Mathf.Abs(r-112)<1.2f||Mathf.Abs(r-78)<1||x==20||x==363||y==20||y==491;float a=Mathf.Atan2(y-285,x-192);if(r>88&&r<101&&Mathf.Abs(Mathf.Sin(a*12))<.07f)ink=true;if(y>191&&y<381&&(Mathf.Abs(x-(192+(381-y)*.57f))<1||Mathf.Abs(x-(192-(381-y)*.57f))<1))ink=true;if(y==191&&x>83&&x<301)ink=true;if(ink)p*=.4f;p*=.97f+Mathf.PerlinNoise(x*.3f,y*.3f)*.06f;c[y*w+x]=p;}t.SetPixels(c);t.Apply();return t;}
    public static Texture2D Rounded(){int n=64;var t=new Texture2D(n,n,TextureFormat.RGBA32,false);var p=new Color[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){Vector2 q=new Vector2(Mathf.Max(Mathf.Abs(x-31.5f)-15,0),Mathf.Max(Mathf.Abs(y-31.5f)-15,0));p[y*n+x]=new Color(1,1,1,Mathf.Clamp01(16.5f-q.magnitude));}t.SetPixels(p);t.Apply();return t;}
    public static Texture2D Dot(){var t=new Texture2D(32,32,TextureFormat.RGBA32,false);var p=new Color[1024];for(int y=0;y<32;y++)for(int x=0;x<32;x++){float a=Mathf.Clamp01(1-Vector2.Distance(new Vector2(x,y),new Vector2(15.5f,15.5f))/15.5f);p[y*32+x]=new Color(1,1,1,a*a);}t.SetPixels(p);t.Apply();return t;}
}
}
